import json
from itertools import combinations

events = ["R", "S", "H", "L", "P"]  # long-distance run, sprint, high jump, long jump, shot put

def valid(sel):
    s = set(sel)
    if not (1 <= len(s) <= 2):
        return False
    if "R" in s and (s & {"S", "H", "L"}):
        return False
    if "L" in s and (s & {"R", "P"}):
        return False
    return True

# All valid selections for a grade that includes long-distance running
selections = []
for k in (1, 2):
    for c in combinations(events, k):
        if "R" in c and valid(c):
            selections.append(c)

# Options: each lists the alternative events (the "or" choices)
options = {
    "A": ["S", "P"],
    "B": ["S", "L"],
    "C": ["P", "H"],
    "D": ["R", "H"],
}

def possible(opt_events):
    # Possible if some valid selection containing R includes at least one of the listed events
    return any(any(e in sel for e in opt_events) for sel in selections)

results = {k: possible(v) for k, v in options.items()}
impossible = [k for k, v in results.items() if not v]

if len(impossible) == 1:
    answer = impossible[0]
else:
    print("UNSUPPORTED")
    raise SystemExit

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "valid_selections_with_run": ["".join(s) for s in selections],
        "option_possible": results
    }
}))
